package com.library.ui;
import com.library.service.ReportService; import com.library.session.SessionManager; import javax.swing.*; import javax.swing.border.EmptyBorder; import java.awt.*; import java.util.*;
public class AdminDashboard extends JFrame { private final JPanel cards=new JPanel(new GridLayout(2,3,12,12)); public AdminDashboard(){super("Smart Library System - Admin");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1180,720);setMinimumSize(new Dimension(1000,650));setLocationRelativeTo(null);JPanel root=new JPanel(new BorderLayout());root.setBackground(UI.BG);root.add(sidebar(),BorderLayout.WEST);cards.setBackground(UI.BG);cards.setPreferredSize(new Dimension(840,250));JPanel content=new JPanel(new FlowLayout(FlowLayout.LEFT,28,28));content.setBackground(UI.BG);content.add(cards);root.add(new JScrollPane(content),BorderLayout.CENTER);add(root);refresh();} private JComponent sidebar(){JPanel p=new JPanel();p.setBackground(UI.NAVY);p.setPreferredSize(new Dimension(210,0));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel("  LIBRARY ADMIN");h.setForeground(Color.WHITE);h.setFont(new Font("Segoe UI",Font.BOLD,18));h.setBorder(new EmptyBorder(28,8,26,8));p.add(h);add(p,"Dashboard",this::refresh);add(p,"Books",()->UI.openAdminPage(this,new BookManagementFrame()));add(p,"Members",()->UI.openAdminPage(this,new MemberManagementFrame()));add(p,"Issue Book",()->UI.openAdminPage(this,new IssueBookFrame()));add(p,"Return Book",()->UI.openAdminPage(this,new ReturnBookFrame()));add(p,"Transactions",()->UI.openAdminPage(this,new TransactionFrame()));add(p,"Reports",()->UI.openAdminPage(this,new ReportFrame()));add(p,"Change Student Password",()->new StudentPasswordFrame().setVisible(true));add(p,"Change Admin Password",this::changePassword);add(p,"Logout",()->{SessionManager.logout();dispose();new RoleSelectionFrame().setVisible(true);});return p;} private void add(JPanel p,String label,Runnable action){JButton b=new JButton(label);b.setMaximumSize(new Dimension(210,46));b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setForeground(Color.WHITE);b.setFont(new Font("Segoe UI",Font.BOLD,14));b.setBackground(UI.NAVY);b.setContentAreaFilled(false);b.setBorderPainted(false);b.addActionListener(e->action.run());p.add(b);p.add(Box.createVerticalStrut(4));} private void changePassword(){JTextField id=new JTextField();JPasswordField old=new JPasswordField(),fresh=new JPasswordField();Object[] fields={"Admin ID",id,"Current password",old,"New password",fresh};if(JOptionPane.showConfirmDialog(this,fields,"Change Admin Password",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{new com.library.service.AuthService().changeAdminPassword(id.getText(),new String(old.getPassword()),new String(fresh.getPassword()));UI.info(this,"Admin password changed successfully.");}catch(Exception e){UI.error(this,e);}} private void refresh(){try{cards.removeAll();Map<String,Number> s=new ReportService().statistics();s.forEach((k,v)->cards.add(card(k,k.equals("Total Fine")?UI.rupee((java.math.BigDecimal)v):String.valueOf(v))));cards.revalidate();cards.repaint();}catch(Exception e){UI.error(this,e);}} private JPanel card(String label,String value){JPanel p=UI.card(label,value);p.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));p.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){if(label.contains("Member"))UI.openAdminPage(AdminDashboard.this,new MemberManagementFrame());else if(label.contains("Book")||label.contains("Copies"))UI.openAdminPage(AdminDashboard.this,new BookManagementFrame());else if(label.contains("Fine")||label.contains("Overdue"))UI.openAdminPage(AdminDashboard.this,new TransactionFrame());}});return p;} }
